#include <stdio.h>
#define MAX 1000
int main(void) {
    int q[MAX], head = 0, tail = 0, x;
    while (scanf("%d", &x) == 1 && x != 0) q[tail++] = x;
    for (int i = head; i < tail; i++) {
        printf("%d", q[i]);
        if (i + 1 < tail) printf(" ");
    }
    printf("\n");
    return 0;
}
